__global__ void grouped_warp_cholesky_32(
    const float* __restrict__ input,
    float* __restrict__ output,
    int batch
) {
    constexpr int N = 32;
    constexpr int LD = 33;
    constexpr int MATRICES_PER_BLOCK = 4;
    __shared__ float storage[MATRICES_PER_BLOCK * N * LD];
    const int warp = threadIdx.x / 32;
    const int lane = threadIdx.x % 32;
    float* tile = storage + warp * N * LD;
    const int first_matrix =
        static_cast<int>(blockIdx.x) * MATRICES_PER_BLOCK + warp;
    const int matrix_stride = static_cast<int>(gridDim.x) * MATRICES_PER_BLOCK;
    for (int matrix = first_matrix; matrix < batch; matrix += matrix_stride) {
        const int base = matrix * N * N;
        const float* src = input + base;
        float* dst = output + base;

        // Four 8-lane vector groups stage four complete rows per iteration.
        // The padded shared layout retains conflict-free row-register loads.
        #pragma unroll
        for (int row_base = 0; row_base < N; row_base += 4) {
            const int row = row_base + lane / 8;
            const int col = (lane % 8) * 4;
            float4 values = *reinterpret_cast<const float4*>(
                src + row * N + col
            );
            if (row < col) values.x = 0.0f;
            if (row < col + 1) values.y = 0.0f;
            if (row < col + 2) values.z = 0.0f;
            if (row < col + 3) values.w = 0.0f;
            tile[row * LD + col] = values.x;
            tile[row * LD + col + 1] = values.y;
            tile[row * LD + col + 2] = values.z;
            tile[row * LD + col + 3] = values.w;
