        #pragma unroll
        for (int col = 0; col < N; ++col) {
            tile[lane * LD + col] = row_values[col];
        }
        __syncwarp();

        #pragma unroll
        for (int row_base = 0; row_base < N; row_base += 4) {
            const int row = row_base + lane / 8;
            const int col = (lane % 8) * 4;
            const float4 values = make_float4(
                tile[row * LD + col],
                tile[row * LD + col + 1],
                tile[row * LD + col + 2],
                tile[row * LD + col + 3]
